/* Curated problem bank. { id, title, src, url, topics: [primary, ...], diff 1..5, hints: [...], note?, tags? }
   Difficulty: 1 = warm-up, 2 = standard application, 3 = needs an idea, 4 = hard regional problem, 5 = expert. */
const cses = (id, title, topics, diff, hints = [], extra = {}) => ({ id: `cses-${id}`, title, src: 'CSES', url: `https://cses.fi/problemset/task/${id}`, topics, diff, hints, ...extra });
const cf = (contest, idx, title, topics, diff, hints = [], extra = {}) => ({ id: `cf-${contest}${idx}`, title, src: 'Codeforces', url: `https://codeforces.com/problemset/problem/${contest}/${idx}`, topics, diff, hints, ...extra });
const ac = (contest, task, title, topics, diff, hints = [], extra = {}) => ({ id: `ac-${task}`, title, src: 'AtCoder', url: `https://atcoder.jp/contests/${contest}/tasks/${task}`, topics, diff, hints, ...extra });
const kattis = (id, title, topics, diff, hints = [], extra = {}) => ({ id: `kattis-${id}`, title, src: 'Kattis', url: `https://open.kattis.com/problems/${id}`, topics, diff, hints, ...extra });

